from typing import Tuple, List
import numpy as np
import pandas as pd
from solver import Algorithm


class Evolved(Algorithm):
    """Lossless bounded optimizer for serialized character-prefix reuse."""

    def __init__(self, df: pd.DataFrame = None):
        """Store the optional source dataframe and shape metadata."""
        self.df = df
        self.num_rows = 0
        self.num_cols = 0

    @staticmethod
    def _cell_text(value) -> str:
        """Convert a scalar to evaluator text, mapping scalar missing values to ''. """
        try:
            missing = pd.isna(value)
            if isinstance(missing, (bool, np.bool_)) and bool(missing):
                return ""
        except Exception:
            pass
        return str(value)

    @staticmethod
    def _lcp(left: str, right: str) -> int:
        """Compute LCP length using binary-search slice comparisons in C."""
        limit = min(len(left), len(right))
        low, high = 0, limit
        while low < high:
            middle = (low + high + 1) // 2
            if left[:middle] == right[:middle]:
                low = middle
            else:
                high = middle - 1
        return low

    @classmethod
    def _trie_score(cls, strings: List[str]) -> int:
        """Return exact sorted-adjacent serialized Trie reuse."""
        if len(strings) < 2:
            return 0
        ordered = sorted(strings)
        total = 0
        for index in range(1, len(ordered)):
            total += cls._lcp(ordered[index - 1], ordered[index])
        return total

    @staticmethod
    def _make_strings(cells, orders) -> List[str]:
        """Serialize each source row according to its row-specific permutation."""
        return [
            "".join(cells[row, column] for column in orders[row])
            for row in range(cells.shape[0])
        ]

    def _global_order(self, cells) -> List[int]:
        """Rank columns by length-weighted repeated-value pair frequency."""
        n, m = cells.shape
        ranked = []

        for column in range(m):
            counts = {}
            for value in cells[:, column]:
                counts[value] = counts.get(value, 0) + 1

            score = sum(
                len(value) * count * (count - 1)
                for value, count in counts.items()
            )
            ranked.append((score, column))

        ranked.sort(key=lambda item: (-item[0], item[1]))
        return [column for _, column in ranked]

    def _conditional_orders(self, cells) -> List[List[int]]:
        """Choose a repeated leading field and rank suffixes inside each value group."""
        n, m = cells.shape
        if m <= 1:
            return [list(range(m)) for _ in range(n)]

        lead_candidates = []
        for column in range(m):
            counts = {}
            for value in cells[:, column]:
                counts[value] = counts.get(value, 0) + 1

            score = sum(
                len(value) * count * (count - 1)
                for value, count in counts.items()
            )
            lead_candidates.append((score, column))

        lead = max(
            lead_candidates,
            key=lambda item: (item[0], -item[1])
        )[1]

        groups = {}
        for row in range(n):
            groups.setdefault(cells[row, lead], []).append(row)

        remaining = [column for column in range(m) if column != lead]
        result = [None] * n

        for rows in groups.values():
            ranked = []
            for column in remaining:
                counts = {}
                for row in rows:
                    value = cells[row, column]
                    counts[value] = counts.get(value, 0) + 1

                score = sum(
                    len(value) * count * (count - 1)
                    for value, count in counts.items()
                )
                ranked.append((score, column))

            ranked.sort(key=lambda item: (-item[0], item[1]))
            order = [lead] + [column for _, column in ranked]

            for row in rows:
                result[row] = order[:]

        return result

    @staticmethod
    def _reverse_segment(order: List[int], left: int, right: int) -> List[int]:
        """Return a copy with the inclusive segment left:right reversed."""
        result = order[:]
        result[left:right + 1] = reversed(result[left:right + 1])
        return result

    def _best_reversal(self, cells, seed: List[int]) -> List[int]:
        """Select the best of at most eighteen exact global segment reversals."""
        n, m = cells.shape
        if m < 2:
            return seed[:]

        prefix = min(10, m)
        intervals = []

        # Deterministically enumerate intervals in the high-repeat prefix.
        for left in range(prefix):
            for right in range(left + 1, prefix):
                intervals.append((left, right))
                if len(intervals) >= 17:
                    break
            if len(intervals) >= 17:
                break

        # Include one reversal crossing into the lower-ranked tail.
        if m > prefix and len(intervals) < 18:
            crossing = (
                max(0, prefix - 2),
                min(m - 1, prefix + 2),
            )
            if crossing not in intervals:
                intervals.append(crossing)

        seed_orders = [seed[:] for _ in range(n)]
        best_score = self._candidate(cells, seed_orders)[0]
        best_order = seed[:]

        for left, right in intervals[:18]:
            trial = self._reverse_segment(seed, left, right)
            trial_orders = [trial[:] for _ in range(n)]
            score = self._candidate(cells, trial_orders)[0]
            if score > best_score:
                best_score = score
                best_order = trial

        return best_order

    def _candidate(self, cells, orders):
        """Serialize, score, and lexicographically sort one candidate."""
        strings = self._make_strings(cells, orders)
        score = self._trie_score(strings)
        row_order = sorted(
            range(len(strings)),
            key=lambda row: (strings[row], row)
        )
        return score, strings, row_order

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        """Build global, bounded-reversal, and conditional candidates and return the exact best."""
        n, m = df.shape
        self.num_rows = n
        self.num_cols = m

        if n == 0 or m == 0:
            return df.copy(), [[] for _ in range(n)]

        raw = df.to_numpy(dtype=object, copy=True)
        cells = np.empty((n, m), dtype=object)

        for row in range(n):
            for column in range(m):
                cells[row, column] = self._cell_text(raw[row, column])

        global_order = self._global_order(cells)

        # Structural constraints are preserved conservatively by retaining
        # the incumbent global order rather than applying unconstrained
        # segment reversals.
        constrained = bool(col_merge or one_way_dep)
        if constrained or n * m > 250000:
            reversal_order = global_order[:]
        else:
            reversal_order = self._best_reversal(cells, global_order)

        conditional = self._conditional_orders(cells)

        candidates = [
            ([global_order[:] for _ in range(n)], 0),
            ([reversal_order[:] for _ in range(n)], 1),
            (conditional, 2),
        ]

        best = None
        for orders, candidate_id in candidates:
            score, strings, row_order = self._candidate(cells, orders)
            signature = tuple(orders[0]) if orders else ()
            choice = (score, tuple(-column for column in signature), -candidate_id)

            if best is None or choice > best[0]:
                best = (choice, strings, row_order, orders)

        _, _, row_order, orders = best

        output = np.empty((n, m), dtype=object)
        column_orders = []

        for destination, source in enumerate(row_order):
            source_order = orders[source]
            output[destination, :] = [
                raw[source, column] for column in source_order
            ]
            column_orders.append([
                df.columns[column] for column in source_order
            ])

        result = pd.DataFrame(output, columns=df.columns)
        return result, column_orders

responses:
The main improvement is a bounded global segment-reversal search seeded by the required length-weighted global ordering. Unlike adjacent swaps, reversing a segment can change both sides of several field boundaries at once. Each reversal is evaluated using the exact sorted-string LCP objective, so the heuristic is only used to generate candidates; selection remains objective-driven.

The search is disabled for constrained or very large inputs to keep runtime bounded. The conditional candidate remains available as an independent alternative, and all returned rows retain their original values and row-specific column permutations.

